  // ---------- DOM: start hint, close-up card, control bar, end bar ----------
  const startHint = document.createElement('div'); startHint.id = 'pstart'; startHint.textContent = 'Press ▶ Next or click to begin';
  stage.appendChild(startHint); startHint.addEventListener('click', () => next());
  const cuBack = document.createElement('div'); cuBack.id = 'cuback'; stage.appendChild(cuBack);
  const card = document.createElement('div'); card.id = 'cucard'; stage.appendChild(card);
  cuBack.addEventListener('click', () => closeCU());

  const IC = (d, fill) => `<svg width="22" height="22" viewBox="0 0 24 24" aria-hidden="true" fill="${fill ? 'currentColor' : 'none'}" stroke="${fill ? 'none' : 'currentColor'}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${d}</svg>`;
  const I = { prev: IC('<path d="M6 5v14"/><path d="M19 5 9 12l10 7z" fill="currentColor"/>'), next: IC('<path d="M18 5v14"/><path d="m5 5 10 7-10 7z" fill="currentColor"/>'),
    play: IC('<path d="M7 4.5v15l13-7.5z"/>', 1), pause: IC('<rect x="6" y="4.5" width="4" height="15" rx="1.2"/><rect x="14" y="4.5" width="4" height="15" rx="1.2"/>', 1),
    ff: IC('<path d="M3 5.5v13l9-6.5z M12 5.5v13l9-6.5z"/>', 1), rew: IC('<path d="M3 12a9 9 0 1 0 3-6.7"/><path d="M3 4v5h5"/>'), home: IC('<path d="M3 11.5 12 4l9 7.5"/><path d="M5.5 10v9.5h13V10"/>') };
  const bar = document.createElement('div'); bar.id = 'pbar';
  bar.innerHTML = `<button id="bReset" title="Rewind to start (Home)" aria-label="Rewind to start">${I.rew}</button><span class="sep"></span>
    <button id="bPrev" title="Previous (←)" aria-label="Previous">${I.prev}</button><button id="bPlay" title="Play (Space)" aria-label="Play">${I.play}</button>
    <button id="bNext" title="Next (→)" aria-label="Next">${I.next}</button><button id="bFF" title="Fast-forward" aria-label="Fast-forward">${I.ff}</button>${EMBED ? '' : '<span class="sep"></span><a id="bAll" href="index.html" title="All flows" aria-label="All flows">' + I.home + '</a>'}
    <span class="ctr" id="bCtr"></span>`;
  stage.appendChild(bar); if (IDLE) bar.style.display = 'none';
  let wakeT = 0; addEventListener('mousemove', () => { bar.classList.add('awake'); wakeT = performance.now(); });
  E('bPrev').onclick = () => prev(); E('bNext').onclick = () => next(); E('bReset').onclick = () => reset();
  E('bPlay').onclick = () => setMode(mode === 'play' ? 'step' : 'play'); E('bFF').onclick = () => setMode(mode === 'ff' ? 'step' : 'ff');

  const endBar = document.createElement('div');
  endBar.innerHTML = `<button id="rs" type="button">${I.rew}<span>Watch again</span></button>` + (EMBED ? `<button id="hub" type="button">${I.home}<span>Architecture</span></button>` : `<a id="hub" href="index.html">${I.home}<span>All flows</span></a>`);
  Object.assign(endBar.style, { position: 'fixed', left: '50%', bottom: '9%', transform: 'translateX(-50%)', display: 'none', gap: '14px', zIndex: 150, alignItems: 'center' });
  document.body.appendChild(endBar);
  const bs = 'font:600 16px -apple-system,BlinkMacSystemFont,"SF Pro Text",Inter,"Segoe UI",Arial;padding:11px 20px;border-radius:999px;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;gap:8px;';
  endBar.querySelector('#rs').style.cssText = bs + 'background:#1D1D1F;color:#fff;border:0;box-shadow:0 8px 24px rgba(0,0,0,.18)';
  endBar.querySelector('#hub').style.cssText = bs + 'background:rgba(255,255,255,.85);color:#1D1D1F;border:1px solid rgba(0,0,0,.08)';
  endBar.querySelector('#rs').onclick = () => reset();
  if (EMBED) endBar.querySelector('#hub').onclick = () => toParent({ type: 'home' });

  // ---------- navigation ----------
  function moving() { return t < target - 1e-6; }
  function next() {
    if (closeup || IDLE) return;
    if (moving()) { t = target; return; }                    // finish the current move instantly
    if (idx >= PAUSES.length - 1) return;
    idx++; target = PAUSES[idx].t; idle = 0;
    if (idx === 1 && t < 1.7) t = 1.7;                        // skip the wait before the opening dissolves
  }
  function prev() { if (closeup || IDLE) return; setMode('step'); idx = Math.max(FIRST, idx - 1); t = target = PAUSES[idx].t; idle = 0; }
  function reset() { closeCU(true); setMode('step'); idx = FIRST; t = target = PAUSES[FIRST].t; idle = 0; }
  function setMode(m) { if (closeup && m !== 'step') return; mode = m; E('bPlay').classList.toggle('on', m === 'play'); E('bFF').classList.toggle('on', m === 'ff');
    E('bPlay').innerHTML = m === 'play' ? I.pause : I.play; E('bPlay').title = m === 'play' ? 'Pause (Space)' : 'Play (Space)'; if (m !== 'step' && !moving()) next(); }

