  ['a', 'b', 'w', 'd', 'm', 'c'].forEach(l => { const p = E(l + '-pk'); if (p) p.addEventListener('click', e => { e.stopPropagation(); const n = performance.now(); if (n - lastBall < 400) return; lastBall = n; setMode('step'); next(); }); });

