    { const v = IDLE ? 'idle' : (t >= EC - 0.2 ? 'end' : (TRS.some(tr => camP(tr, t) > 0.5) ? 'zoom' : 'arch'));
      if (EMBED && v !== window.__view) { window.__view = v; toParent({ type: 'view', view: v }); } }
